Showhue", AccessLevel.GameMaster, new CommandEventHandler( Showhue_OnCommand ) );    }    [Usage( "Showhue" )]    [Description( "Show hue" )]    public static void Showhue_OnCommand( CommandEventArgs e )    {      e.Mobile.SendGump( new ShowhueGump( e.Mobile ) );    }    public ShowhueGump(ShowhueGump gump): base(50,40) {      _item=gump._item;      m_From = gump.m_From;      m_newstart = gump.m_newstart;      m_From.SendMessage("sg item:{0} hue:{1}", _item,m_newstart);      m_From.CloseGump( typeof( ShowhueGump ) );      AddDetails( m_newstart);    }    public ShowhueGump( Mobile from ) : base( 50, 40 )    {      _item=I;      m_From = from;      m_newstart = 0;      AddDetails( m_newstart );    }    private void AddDetails( int index)    {      try{      AddPage( 0 );      int w=W*T+72;      int skip=10;            AddBackground( 0, 0, w, 100+H*T, 9270 );      AddBackground( 11, 35, W*T+50, 55+H*T, 3000 );      AddLabelCropped( 13, 13, 150, 20, 1152, "Nika's ShowhueGump" );      //adding items from right to left      w-=13; //border      w-=17; //button      AddButton(w, 14, 0x15E1, 0x15E5, -2, GumpButtonType.Reply, 0 );       w-=17; //button      AddButton(w, 14, 0x15E3, 0x15E7, -1, GumpButtonType.Reply, 0 );             w-=skip; //skip      w-=17; //button      AddButton( w, 13, 0x15E2, 0x15E6, -3, GumpButtonType.Reply, 0 );      w-=60+4;      AddBackground(w, 13, 60+4, 20, 3000 );      AddTextEntry(w+2, 13, 60, 20, 10, 20, "" );      w-=15; //20      AddLabelCropped(w,13,65,20, 1152,"id");      w-=skip;      w-=17;      AddButton( w, 13, 0x15E2, 0x15E6, -4, GumpButtonType.Reply, 0 );      w-=40;//65      AddLabelCropped(w,13,65,20, 1152,"copy");/*      w-=skip;      w-=17;      AddButton(w, 13, _target?0x9cf:0x9ce,  _target?0x9ce:0x9cf, -5, GumpButtonType.Reply, 0 );      w-=40;//65      AddLabelCropped(w,13,65,20, 1152,"target");      w-=skip;      w-=17;      AddButton(w, 13, 0x15E2, 0x15E6, -6, GumpButtonType.Reply, 0 );      w-=100+4;      AddBackground(w, 13, 100+4, 20, 3000 );      AddTextEntry(w+2, 13, 100, 20, 10, 21, name );      w-=40; //65       AddLabelCropped(w,13,65,20, 1152,"name");*/                          //grid      for ( int i = 0; i < H; ++ i )      {        AddLabel( 18, 70 + (i * T), 1152, String.Format( "{0}", index + (i * W) ) ); //"0x{0:X}" for hex        for ( int j = 0; j < W; ++ j )        {          AddButton( 70 + (j * T), 50 + (i * T), 0x24b2, 0x24b2, index + (i * W) + (j), GumpButtonType.Reply, 0 );          AddItem( 70 + (j * T), 50 + (i * T), _item,index+(i*W)+j );        }      }      }catch{}    }    //use in try as convert might give an exception        int toInt(String s){      int b=10;      if (s.StartsWith("0x") || s.StartsWith("0X")){        s=s.Substring(2);        b=16;      }      return Convert.ToInt32(s,b);    }        public void setView(int id,int hue){      if (id!=-1) {        m_newstart=hue;        _item=id;      }      m_From.SendGump( new ShowhueGump( this));    }    void updateGump(Mobile from, RelayInfo info ){        from.SendGump( new ShowhueGump( this));    }        public override void OnResponse( NetState state, RelayInfo info )    {      Mobile from = state.Mobile;      int buttonID = info.ButtonID;      switch(buttonID) {      case 0: //dismiss        break;      case -1: //back        m_newstart -= W*H;        if ( m_newstart < 1 )  m_newstart = 1;        updateGump(from,info);        break;      case -2: //forward        m_newstart += W*H;        updateGump(from,info);        break;      case -3: //jump to page        TextRelay entry = info.GetTextEntry( 20 );        try { m_newstart = toInt(entry.Text); }         catch {}        if ( m_newstart < 1 )  m_newstart = 1;        updateGump(from,info);        break;       case -4: //copy        from.Target=new ShowhueCTarget(this);        //updateGump(from,info);        break;/*      case -5: //toggle target        _target=!_target;        updateGump(from,info);      break;      case -6: //setname        from.Target=new ShowhueName(info.GetTextEntry(21).Text);        updateGump(from,info);      break;*/      default: //push image        from.SendMessage("hue {0}", buttonID);        from.Target=new ShowhueTarget(buttonID);        updateGump(from,info);        break;      }    }  }}